import { Pressable, Text, View } from 'react-native';
import { useRouter } from 'expo-router';
import { usePreferences } from '../theme/preferences';

export function GardenInvitation() {
  const { colors, t } = usePreferences();
  const router = useRouter();
  return <View style={{ gap: 12, padding: 20, backgroundColor: colors.surface }}>
    <Text style={{ color: colors.text, fontSize: 24, fontWeight: '700' }}>
      {t('myGarden')}
    </Text>
    <Pressable accessibilityRole="button" accessibilityLabel={t('scan')}
      onPress={() => router.push('/scan')}
      style={{ minHeight: 48, padding: 14, borderRadius: 16,
        justifyContent: 'center', backgroundColor: colors.primary }}>
      <Text style={{ color: colors.onPrimary, fontSize: 17 }}>{t('scan')}</Text>
    </Pressable>
  </View>;
}

import { useEffect } from 'react';
import { AppState } from 'react-native';

type Resource = { disconnect(): Promise<void> };
export function useVoiceCleanup(
  resource: Resource, onFailure: (error: unknown) => void,
) {
  useEffect(() => {
    const stop = () => { void resource.disconnect().catch(onFailure); };
    const subscription = AppState.addEventListener('change', state => {
      if (state !== 'active') stop();
    });
    return () => { subscription.remove(); stop(); };
  }, [resource, onFailure]);
}
